// 자막 번역 결과 캐시 (자막 URL -> {cue 인덱스: 번역문})
const SUB_CACHE = {};

const sha256 = e => {
    const t = e.length,
        r = new Uint32Array(16 * (t + 9 + 63 >> 6));
    for (let s = 0; s < t; s++) r[s >> 2] |= e[s] << 24 - 8 * (3 & s);
    r[t >> 2] |= 128 << 24 - 8 * (3 & t), r[r.length - 2] = Math.floor(t / 536870912), r[r.length - 1] = t << 3;
    const s = Uint32Array.of(1779033703, 3144134277, 1013904242, 2773480762, 1359893119, 2600822924, 528734635, 1541459225),
        n = new Uint32Array(64);
    for (let e = 0; e < r.length; e += 16) {
        for (let t = 0; t < 16; t++) n[t] = r[e + t];
        for (let e = 16; e < 64; e++) {
            const t = n[e - 15],
                r = n[e - 2];
            n[e] = n[e - 16] + ((t >>> 7 | t << 25) ^ (t >>> 18 | t << 14) ^ t >>> 3) + n[e - 7] + ((r >>> 17 | r << 15) ^ (r >>> 19 | r << 13) ^ r >>> 10)
        }
        let t = s[0],
            i = s[1],
            a = s[2],
            o = s[3],
            l = s[4],
            c = s[5],
            h = s[6],
            p = s[7];
        for (let e = 0; e < 64; e++) {
            const r = p + ((l >>> 6 | l << 26) ^ (l >>> 11 | l << 21) ^ (l >>> 25 | l << 7)) + (l & c ^ ~l & h) + SHA_K[e] + n[e] | 0,
                s = ((t >>> 2 | t << 30) ^ (t >>> 13 | t << 19) ^ (t >>> 22 | t << 10)) + (t & i ^ t & a ^ i & a) | 0;
            p = h, h = c, c = l, l = o + r | 0, o = a, a = i, i = t, t = r + s | 0
        }
        s[0] += t, s[1] += i, s[2] += a, s[3] += o, s[4] += l, s[5] += c, s[6] += h, s[7] += p
    }
    const i = new Uint8Array(32);
    for (let e = 0; e < 32; e++) i[e] = s[e >> 2] >>> 24 - 8 * (3 & e) & 255;
    return i
};

const utf8Bytes = e => Uint8Array.from(
        encodeURIComponent(e).replace(/%([0-9A-F]{2})/g,
            (e, t) => String.fromCharCode(parseInt(t, 16))),
        e => e.charCodeAt(0)
    ),
    hexOf = e => Array.from(e, e => e.toString(16).padStart(2, "0")).join(""),
    B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",
    base64Encode = e => {
        let t = "";
        for (let r = 0; r < e.length; r += 3) {
            const s = e[r] << 16 | (e[r + 1] || 0) << 8 | (e[r + 2] || 0);
            t += B64[s >>> 18 & 63] + B64[s >>> 12 & 63] + (r + 1 < e.length ? B64[s >>> 6 & 63] : "=") + (r + 2 < e.length ? B64[63 & s] : "=")
        }
        return t
    },
    base64Decode = e => {
        const t = String(e).replace(/[^A-Za-z0-9+/]/g, ""),
            r = [];
        for (let e = 0; e < t.length; e += 4) {
            const s = [0, 1, 2, 3].reduce((r, s) => r << 6 | (s + e < t.length ? B64.indexOf(t[e + s]) : 0), 0);
            r.push(s >>> 16 & 255), e + 2 < t.length && r.push(s >>> 8 & 255), e + 3 < t.length && r.push(255 & s)
        }
        return Uint8Array.from(r)
    },
    USER_AGENT = "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Mobile Safari/537.36",
    PLAYER = "https://nhplayer.com",
    GEMINI_MODEL = "gemini-3.5-flash-lite",
    GEMINI_PREF_KEY = "hentai_gemini_api_key",
    GENRES = [
        ["", "전체"],
        ["vanilla", "Vanilla"],
        ["romance", "Romance"],
        ["big-boobs", "Big Boobs"],
        ["uncensored", "Uncensored"],
        ["school-girl", "School"],
        ["maid", "Maid"],
        ["comedy", "Comedy"],
        ["incest", "Incest"],
        ["glasses", "Glasses"],
        ["swimsuit", "Swimsuit"],
        ["virgin", "Virgin"],
        ["bondage", "Bondage"],
        ["anal", "Anal"],
        ["loli", "Loli"]
    ],
    sleep = ms => new Promise(resolve => setTimeout(resolve, ms)),
    text = (e, t) => String((t ? e?.selectFirst(t) : e)?.text || "").replace(/\s+/g, " ").trim(),
    attr = (e, t) => String(e?.attr(t) || "").trim(),
    header = (e, t) => String(Object.entries(e?.headers || {}).find(([e]) => e.toLowerCase() === t)?.[1] || ""),
    select = (e, t, r) => ({
        type_name: "SelectFilter",
        type: e,
        name: t,
        state: 0,
        values: r.map(([e, t]) => ({
            type_name: "SelectOption",
            name: t,
            value: e
        }))
    }),
    chosen = (e, t) => {
        const r = (e || []).find(e => e.type === t);
        return r?.values?.[r.state]?.value || ""
    },
    entities = e => String(e || "").replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">"),
    rsc = e => {
        const t = [],
            r = /self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g;
        let s;
        for (; s = r.exec(String(e || ""));) try {
            t.push(JSON.parse(`"${s[1]}"`))
        } catch (e) {
            t.push(s[1].replace(/\\"/g, '"').replace(/\\\\/g, "\\"))
        }
        return t.join("\n")
    },
    objectAt = (e, t) => {
        let r = 0,
            s = !1;
        for (let n = t; n < e.length; n++) {
            const i = e[n];
            if (s) "\\" === i ? n++ : '"' === i && (s = !1);
            else if ('"' === i) s = !0;
            else if ("{" === i) r++;
            else if ("}" === i && 0 === --r) try {
                return JSON.parse(e.slice(t, n + 1))
            } catch (e) {
                return null
            }
        }
        return null
    },
    episodeObjects = (e, t = !1) => {
        const r = [],
            s = new Set,
            n = t ? /\{"v":\{"id":"[^"]+","slug":"[^"]+","title":/g : /\{"id":"[^"]+","slug":"[^"]+","title":/g;
        let i;
        for (; i = n.exec(e);) {
            const a = objectAt(e, i.index + (t ? 5 : 0));
            a?.slug && a.titleSlug && !s.has(a.slug) && (s.add(a.slug), r.push(a)), n.lastIndex = i.index + 1
        }
        return r
    },
    proofOfWork = e => {
        for (let t = 0; t < 1e6; t++)
            if (0 === sha256(utf8Bytes(e + t.toString(16)))[0]) return t.toString(16);
        throw new Error("nhplayer 작업증명에 실패했습니다.")
    },
    hiddenValue = (e, t) => {
        const r = new RegExp(`<(\\w+)[^>]*\\bid="${t}"[^>]*>`).exec(e)?.[0] || "",
            s = /\bvalue="([^"]*)"/.exec(r)?.[1] ?? /\sdata-[\w-]+="([^"]*)"/.exec(r)?.[1];
        return void 0 !== s ? s : new RegExp(`<template[^>]*\\bid="${t}"[^>]*>\\s*<p>([^<]*)</p>`).exec(e)?.[1] || ""
    };

class DefaultExtension extends MProvider {
    get supportsLatest() {
        return !0
    }

    get client() {
        return this._client || (this._client = new Client({
            timeout: 60,
            connectTimeout: 15
        }))
    }

    getHeaders(e) {
        return {
            "User-Agent": USER_AGENT,
            Referer: /^https?:\/\/(?:[^/]+\.)?nhplayer\.com/.test(String(e || "")) ? `${PLAYER}/` : `${this.source.baseUrl}/`
        }
    }

    absolute(e) {
        const t = String(e || "").trim();
        return t ? /^https?:\/\//.test(t) ? t : `${this.source.baseUrl}${t.startsWith("/") ? "" : "/"}${t}` : ""
    }

    seriesSlug(e) {
        const t = /^(?:https?:\/\/(?:www\.)?hentai\.tv)?\/series\/([a-z0-9-]+)\/?(?:[?#]|$)/.exec(String(e || ""));
        if (!t) throw new Error("hentai.tv 시리즈 주소가 아닙니다.");
        return t[1]
    }

    episodeSlug(e) {
        const t = /^(?:https?:\/\/(?:www\.)?hentai\.tv)?\/hentai\/([a-z0-9-]+)\/?(?:[?#]|$)/.exec(String(e || ""));
        if (!t) throw new Error("hentai.tv 회차 주소가 아닙니다.");
        return t[1]
    }

    async html(e, t) {
        const r = await this.client.get(e, t || this.getHeaders(e));
        if (r.statusCode < 200 || r.statusCode >= 300) throw new Error(`요청에 실패했습니다 (HTTP ${r.statusCode}): ${e.replace(/^https?:\/\/[^/]+/, "")}`);
        return String(r.body || "")
    }

    // Gemini API 키 설정
    getSourcePreferences() {
        return [{
            key: GEMINI_PREF_KEY,
            editTextPreference: {
                title: "Gemini API 키",
                summary: "Google AI Studio에서 발급한 Gemini API 키를 입력하세요.",
                value: "",
                dialogTitle: "Gemini API 키 입력",
                dialogMessage: "API 키를 입력하고 저장하세요."
            }
        }];
    }

    // Mangayomi에 저장된 API 키 읽기
    // 앱 버전에 따라 동작하는 방식이 달라서 두 방식을 모두 시도한다.
    getGeminiApiKey() {
        const log = [];

        // 방식 1: getPreferenceValue(sourceId, key)
        try {
            const v = getPreferenceValue(this.source.id, GEMINI_PREF_KEY);
            log.push("gpv=" + typeof v + ":" + String(v ?? "").length);
            if (v && String(v).trim()) {
                this._keyLog = "";
                return String(v).trim();
            }
        } catch (e) {
            log.push("gpv err " + String(e?.message || e).slice(0, 40));
        }

        // 방식 2: SharedPreferences().get(key)
        try {
            const v = new SharedPreferences().get(GEMINI_PREF_KEY);
            log.push("sp=" + typeof v + ":" + String(v ?? "").length);
            if (v && String(v).trim()) {
                this._keyLog = "";
                return String(v).trim();
            }
        } catch (e) {
            log.push("sp err " + String(e?.message || e).slice(0, 40));
        }

        // 실패 원인을 안내 자막에 표시하기 위해 저장
        this._keyLog = log.join(" / ");
        return "";
    }

    // 자막 시간 줄을 표준 WebVTT 형식(HH:MM:SS.mmm --> HH:MM:SS.mmm)으로 정규화
    // (쉼표 구분 SRT식 시간, 시간 생략 형식, 큐 설정 등을 정리)
    normalizeTiming(timing) {
        const m = /(?:(\d+):)?(\d{1,2}):(\d{2})[.,](\d{1,3})\s*-->\s*(?:(\d+):)?(\d{1,2}):(\d{2})[.,](\d{1,3})/.exec(String(timing || ""));
        if (!m) return String(timing || "");

        const f = (h, mi, sec, ms) =>
            String(h || 0).padStart(2, "0") + ":" +
            String(mi).padStart(2, "0") + ":" +
            sec + "." +
            String(ms).padEnd(3, "0");

        return f(m[1], m[2], m[3], m[4]) + " --> " + f(m[5], m[6], m[7], m[8]);
    }

    // WebVTT 자막 파싱
    parseVtt(vtt) {
        const source = String(vtt || "")
            .replace(/^\uFEFF/, "")
            .replace(/\r\n/g, "\n")
            .replace(/\r/g, "\n");

        const blocks = source.split(/\n{2,}/);
        const cues = [];

        for (const block of blocks) {
            const lines = block.split("\n");
            const timeIndex = lines.findIndex(line => line.includes("-->"));

            if (timeIndex < 0) continue;

            const timing = lines[timeIndex].trim();
            const content = lines.slice(timeIndex + 1).join("\n").trim();

            if (!content) continue;

            cues.push({
                timing,
                text: content
            });
        }

        return cues;
    }

    // Gemini 응답에서 번역 배열 추출
    parseGeminiTranslations(responseText) {
        let raw = String(responseText || "").trim()
            .replace(/^```(?:json)?\s*/i, "")
            .replace(/\s*```$/, "")
            .trim();

        let parsed;

        try {
            parsed = JSON.parse(raw);
        } catch (e) {
            const match = raw.match(/\[[\s\S]*\]/);
            if (match) {
                parsed = JSON.parse(match[0]);
            } else {
                throw new Error("Gemini 번역 응답을 JSON으로 해석하지 못했습니다.");
            }
        }

        if (Array.isArray(parsed)) {
            return parsed.map(v => String(v ?? ""));
        }

        if (parsed && Array.isArray(parsed.translations)) {
            return parsed.translations.map(v => String(v ?? ""));
        }

        throw new Error("Gemini 응답에 번역 배열이 없습니다.");
    }

    // 자막 텍스트 묶음 번역 (일시 오류/개수 불일치 시 최대 3회 시도)
    async translateBatch(texts, apiKey) {
        const endpoint =
            `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent`;

        const prompt =
            "Translate the following subtitle lines from English into natural Korean. " +
            "Return ONLY a JSON array of strings. " +
            "The array must contain exactly " + texts.length + " elements, in the same order. " +
            "Do not add explanations, numbering, markdown, or commentary. " +
            "Preserve names, meaning, tone, and subtitle context. " +
            "Do not merge or omit any line.\n\n" +
            JSON.stringify(texts);

        const payload = {
            contents: [{
                role: "user",
                parts: [{
                    text: prompt
                }]
            }],
            generationConfig: {
                temperature: 0.2,
                responseMimeType: "application/json"
            }
        };

        // Mangayomi가 객체 body를 직접 JSON으로 인코딩하므로 문자열로 바꾸지 않는다.
        const body = payload;

        const headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "x-goog-api-key": apiKey
        };

        let lastError = new Error("Gemini 번역 실패");

        for (let attempt = 0; attempt < 3; attempt++) {
            if (attempt > 0) await sleep(1500 * attempt);

            try {
                const response = await this.client.post(endpoint, headers, body);
                const status = response.statusCode;

                if (status < 200 || status >= 300) {
                    let message = "";
                    try {
                        const errorJson = JSON.parse(response.body || "{}");
                        message = errorJson?.error?.message || "";
                    } catch (e) {}

                    const err = new Error(
                        `Gemini API 오류 (HTTP ${status}) ${message}`.trim()
                    );

                    // 429(요청 제한), 5xx는 재시도 / 나머지(키 오류 등)는 즉시 중단
                    if (status === 429 || status >= 500) {
                        lastError = err;
                        continue;
                    }

                    err.fatal = true;
                    throw err;
                }

                let data;

                try {
                    data = JSON.parse(response.body || "{}");
                } catch (e) {
                    throw new Error("Gemini API 응답 JSON을 읽지 못했습니다.");
                }

                const resultText = data?.candidates?.[0]?.content?.parts
                    ?.map(part => String(part.text || ""))
                    .join("\n") || "";

                if (!resultText) {
                    const reason = data?.promptFeedback?.blockReason ||
                        data?.candidates?.[0]?.finishReason ||
                        "응답 내용 없음";
                    throw new Error(`Gemini 번역 결과가 비어 있습니다: ${reason}`);
                }

                const translations = this.parseGeminiTranslations(resultText);

                // 줄 수가 다르면 자막이 한 줄씩 밀리므로 재시도
                if (translations.length !== texts.length) {
                    lastError = new Error(
                        `번역 줄 수 불일치 (${translations.length}/${texts.length})`
                    );
                    continue;
                }

                return translations;
            } catch (e) {
                if (e && e.fatal) throw e;
                lastError = e;
            }
        }

        throw lastError;
    }

    // 전체 VTT 번역
    async translateSubtitleToVtt(subtitleUrl, apiKey) {
        const response = await this.client.get(
            subtitleUrl,
            {
                "User-Agent": USER_AGENT,
                Referer: `${PLAYER}/`,
                Accept: "text/vtt,text/plain,*/*"
            }
        );

        if (response.statusCode < 200 || response.statusCode >= 300) {
            throw new Error(`영어 자막 다운로드 실패 (HTTP ${response.statusCode})`);
        }

        const originalVtt = String(response.body || "")
            .replace(/^\uFEFF/, "");

        if (!originalVtt.trim()) {
            throw new Error("영어 자막 파일이 비어 있습니다.");
        }

        const cues = this.parseVtt(originalVtt);

        if (!cues.length) {
            throw new Error("WebVTT 자막 구간을 찾지 못했습니다.");
        }

        // 앱의 getVideoList 제한시간(약 40초) 때문에 병렬로 번역하고,
        // 시간 예산을 넘기면 남은 구간은 영어 원문으로 두고 캐시에 쌓아둔다.
        // (같은 영상을 다시 열면 캐시된 부분은 건너뛰고 나머지를 이어서 번역)
        const BATCH = 40,
            CONCURRENCY = 4,
            BUDGET_MS = 20000,
            HARD_CAP_MS = 26000;

        const cache = SUB_CACHE[subtitleUrl] || (SUB_CACHE[subtitleUrl] = {});
        const deadline = Date.now() + BUDGET_MS;

        const pending = [];
        for (let i = 0; i < cues.length; i += BATCH) {
            let complete = true;
            for (let j = i; j < Math.min(i + BATCH, cues.length); j++) {
                if (!cache[j]) {
                    complete = false;
                    break;
                }
            }
            if (!complete) pending.push(i);
        }

        let next = 0,
            lastError = null,
            fatalError = null;

        const worker = async () => {
            while (next < pending.length && Date.now() < deadline && !fatalError) {
                const start = pending[next++];
                const batch = cues.slice(start, start + BATCH);

                try {
                    const out = await this.translateBatch(
                        batch.map(cue => cue.text),
                        apiKey
                    );

                    for (let j = 0; j < batch.length; j++) {
                        const tr = String(out[j] || "").trim();
                        if (tr) cache[start + j] = tr;
                    }
                } catch (e) {
                    lastError = e;
                    if (e && e.fatal) fatalError = e;
                }
            }
        };

        if (pending.length) {
            await Promise.race([
                Promise.all(Array.from({
                    length: Math.min(CONCURRENCY, pending.length)
                }, () => worker())),
                sleep(HARD_CAP_MS)
            ]);
        }

        if (fatalError) throw fatalError;

        let done = 0;
        for (let i = 0; i < cues.length; i++) {
            if (cache[i]) done++;
        }

        // 하나도 번역하지 못했으면 원인을 오류 자막으로 표시
        if (done === 0) {
            throw lastError || new Error("번역된 자막이 없습니다. 잠시 후 다시 시도하세요.");
        }

        // 플레이어에 전달할 실제 WebVTT 문자열 생성
        let finalVtt = "WEBVTT\n\n";

        // 일부만 번역된 경우에만 시작 직후 안내를 잠깐 표시
        if (done < cues.length) {
            finalVtt += "00:00:00.500 --> 00:00:04.000\n";
            finalVtt += "[Gemini 번역 " + done + "/" + cues.length + "줄 - 나머지는 영어, 다시 열면 이어서 번역]\n\n";
        }

        for (let i = 0; i < cues.length; i++) {
            finalVtt += this.normalizeTiming(cues[i].timing) + "\n";
            finalVtt += (cache[i] || cues[i].text) + "\n\n";
        }

        return finalVtt.trim() + "\n";
    }

    series(e) {
        const t = [],
            r = new Set;

        for (const s of e) {
            const e = String(s.titleSlug || ""),
                n = String(s.title || "").trim();

            /^[a-z0-9-]+$/.test(e) && n && !r.has(e) && (
                r.add(e),
                t.push({
                    name: n,
                    link: `/series/${e}`,
                    imageUrl: this.absolute(s.cover || s.thumb)
                })
            );
        }

        return t;
    }

    async getPopular(e) {
        if (!Number.isSafeInteger(e) || e < 1) {
            throw new Error("올바른 페이지 번호가 아닙니다.");
        }

        const t = await this.html(
                `${this.source.baseUrl}/series${e > 1 ? `?page=${e}` : ""}`
            ),
            r = new Document(t).body,
            s = [];

        for (const e of r.select("a.cat-card")) {
            let t;

            try {
                t = `/series/${this.seriesSlug(attr(e, "href"))}`;
            } catch (e) {
                continue;
            }

            const r = e.selectFirst("img"),
                n = text(e, ".cat-title") || attr(r, "alt");

            n && s.push({
                name: n,
                link: t,
                imageUrl: this.absolute(attr(r, "src"))
            });
        }

        return {
            list: s,
            hasNextPage: new RegExp(`href="[^"]*\\?page=${e + 1}"`).test(t)
        };
    }

    async getLatestUpdates(e) {
        if (e > 1) {
            return {
                list: [],
                hasNextPage: !1
            };
        }

        const t = rsc(await this.html(`${this.source.baseUrl}/`)),
            r = t.indexOf('"items":[');

        return {
            list: this.series(
                episodeObjects(r >= 0 ? t.slice(r) : t)
            ).slice(0, 60),
            hasNextPage: !1
        };
    }

    async search(e, t, r) {
        const s = String(e || "").trim();

        if (s) {
            if (t > 1) {
                return {
                    list: [],
                    hasNextPage: !1
                };
            }

            const e = `${this.source.baseUrl}/api/search?q=${encodeURIComponent(s.slice(0, 100))}&limit=40`;
            let r;

            try {
                r = JSON.parse(await this.html(e, {
                    ...this.getHeaders(e),
                    Accept: "application/json"
                }));
            } catch (e) {
                throw new Error("검색 응답을 읽지 못했습니다.");
            }

            return {
                list: this.series(Array.isArray(r?.videos) ? r.videos : []),
                hasNextPage: !1
            };
        }

        const n = chosen(r, "genre");

        if (!n) return this.getPopular(t);

        const i = await this.html(
            `${this.source.baseUrl}/genre/${n}${t > 1 ? `?page=${t}` : ""}`
        );

        return {
            list: this.series(episodeObjects(rsc(i), !0)),
            hasNextPage: new RegExp(`href="[^"]*\\?page=${t + 1}"`).test(i)
        };
    }

    getFilterList() {
        return [{
            type_name: "HeaderFilter",
            name: "검색어가 있으면 장르는 무시됩니다"
        }, select("genre", "장르", GENRES)];
    }

    async getDetail(e) {
        const t = this.seriesSlug(e),
            r = `${this.source.baseUrl}/series/${t}`,
            s = await this.html(r),
            n = episodeObjects(rsc(s), !0)
                .filter(e => e.titleSlug === t && Number.isFinite(Number(e.ep)))
                .sort((e, t) => Number(e.ep) - Number(t.ep));

        if (!n.length) {
            throw new Error("회차를 찾지 못했습니다.");
        }

        const i = text(new Document(s).body, "h1") || String(n[0].title || "").trim(),
            a = [...new Set(
                n.flatMap(e => Array.isArray(e.tags) ? e.tags : [])
                    .map(e => String(e).trim())
                    .filter(Boolean)
            )].slice(0, 20);

        return {
            name: i,
            link: `/series/${t}`,
            imageUrl: this.absolute(
                /property="og:image" content="([^"]+)"/.exec(s)?.[1] || n[0].cover
            ),
            description: entities(
                /name="description" content="([^"]*)"/.exec(s)?.[1] || ""
            ),
            author: String(n[0].brand || "").trim(),
            genre: a,
            status: 5,
            chapters: n.slice().reverse().map(e => ({
                name: `Episode ${e.ep}`,
                url: `/hentai/${e.slug}`,
                dateUpload: null
            }))
        };
    }

    async getVideoList(e) {
        const t = this.episodeSlug(e),
            r = rsc(await this.html(`${this.source.baseUrl}/hentai/${t}`)),
            s = new RegExp(`\\{"id":"[^"]+","slug":"${t}","title":`).exec(r),
            n = String((s && objectAt(r, s.index))?.embedUrl || "");

        if (!/^https:\/\/nhplayer\.com\/v\/[A-Za-z0-9]+\/?$/.test(n)) {
            throw new Error("플레이어 주소를 찾지 못했습니다.");
        }

        const {
            url: i,
            subtitle: a
        } = await this.nhplayer(n);

        const o = {
            Referer: `${PLAYER}/`
        };

        let l = i;

        if ("function" == typeof createHlsProxyUrl) {
            const e = await createHlsProxyUrl(i, o);

            /^http:\/\/127\.0\.0\.1:\d+\/[^/]+\/playlist\.m3u8\?/.test(String(e)) &&
                (l = String(e).replace("/playlist.m3u8?", "/video.mp4?"));
        }

        const subtitles = [];

        // 원본 영어 자막
        if (a) {
            subtitles.push({
                file: a,
                label: "English"
            });

            // Gemini 번역 자막
            const apiKey = this.getGeminiApiKey();

            if (apiKey) {
                try {
                    const translatedVtt = await this.translateSubtitleToVtt(
                        a,
                        apiKey
                    );

                    if (
                        translatedVtt &&
                        /^WEBVTT(?:\s|$)/.test(translatedVtt)
                    ) {
                        subtitles.unshift({
                            file: translatedVtt,
                            label: "한국어 (Gemini 번역)"
                        });
                    } else {
                        throw new Error("번역 결과가 올바른 WebVTT 형식이 아닙니다.");
                    }
                } catch (error) {
                    const message = String(error?.message || error)
                        .replace(/[\r\n]/g, " ")
                        .slice(0, 250);

                    // 번역 오류를 플레이어 자막으로 확인할 수 있게 표시
                    const errorVtt =
                        "WEBVTT\n\n" +
                        "00:00:01.000 --> 00:00:08.000\n" +
                        "[Gemini 번역 오류]\n" +
                        message +
                        "\n";

                    subtitles.unshift({
                        file: errorVtt,
                        label: "한국어 번역 오류"
                    });
                }
            } else {
                // 키를 못 읽은 이유를 함께 표시 (진단용)
                const diag = this._keyLog ?
                    "\n" + String(this._keyLog).replace(/[\r\n]/g, " ").slice(0, 150) :
                    "";

                const noKeyVtt =
                    "WEBVTT\n\n" +
                    "00:00:01.000 --> 00:00:06.000\n" +
                    "[Gemini API 키를 확장 설정에 입력하세요.]" +
                    diag +
                    "\n";

                subtitles.unshift({
                    file: noKeyVtt,
                    label: "한국어 번역 설정 안내"
                });
            }
        }

        return [{
            url: l,
            originalUrl: i,
            quality: "MP4",
            headers: o,
            subtitles
        }];
    }

    // 기존 nhplayer 영상 추출 및 Proof of Work
    async nhplayer(e) {
        const t = Date.now(),
            r = String(
                /data-id="([^"]+)"/.exec(
                    await this.html(e, {
                        "User-Agent": USER_AGENT,
                        Referer: `${this.source.baseUrl}/`
                    })
                )?.[1] || ""
            ).replace(/&amp;/g, "&");

        if (!r.startsWith("/player.php?")) {
            throw new Error("nhplayer 재생 정보를 찾지 못했습니다.");
        }

        const s = PLAYER + r,
            n = await this.client.get(s, {
                "User-Agent": USER_AGENT,
                Referer: e
            });

        if (n.statusCode < 200 || n.statusCode >= 300) {
            throw new Error(`nhplayer 요청에 실패했습니다 (HTTP ${n.statusCode}).`);
        }

        const i = Date.now(),
            a = String(n.body || ""),
            o = /PHPSESSID=[^;,\s]+/.exec(header(n, "set-cookie"))?.[0] || "",
            l = Object.fromEntries(
                [...(/_pV\s*=\s*\{([^}]*)\}/.exec(a)?.[1] || "")
                    .matchAll(/(\w+):"([^"]*)"/g)]
                    .map(e => [e[1], e[2]])
            ),
            c = String(
                /<script[^>]+src="(player-core-v2\.php[^"]+)"/.exec(a)?.[1] || ""
            ).replace(/&amp;/g, "&");

        if (!l.vid || !c) {
            throw new Error("nhplayer 플레이어 설정을 읽지 못했습니다.");
        }

        const h = {
                "User-Agent": USER_AGENT,
                Referer: s,
                ...o ? {
                    Cookie: o
                } : {}
            },
            p = await this.html(`${PLAYER}/${c}`, h),
            g = /'([0-9a-f]{8}\.[0-9a-f]{16})'/.exec(p)?.[1],
            u = /'([0-9a-f]{16})'/.exec(p)?.[1],
            d = [...p.matchAll(/getElementById\('([^']+)'\)/g)]
                .map(e => e[1])
                .slice(0, 5)
                .map(e => hiddenValue(a, e));

        if (
            !g ||
            !u ||
            d.length < 5 ||
            d.slice(0, 4).some(e => 8 !== e.length) ||
            !d[4]
        ) {
            throw new Error("nhplayer 챌린지 정보를 읽지 못했습니다.");
        }

        const m = proofOfWork(d.join("")),
            f = 800 - (Date.now() - i);

        f > 0 && await new Promise(e => setTimeout(e, f));

        const w = base64Encode(utf8Bytes(JSON.stringify({
                t: Date.now() - t,
                mm: [],
                tm: [],
                cl: [],
                kp: [],
                sc: [],
                i: 0,
                mc: 0,
                tc: 0,
                cc: 0,
                kc: 0,
                b: {
                    sw: 412,
                    sh: 915,
                    aw: 412,
                    ah: 915,
                    cd: 24,
                    pd: 24,
                    tz: -540,
                    hc: 8,
                    dm: 8,
                    pl: "Linux armv8l",
                    lang: "ko-KR",
                    langs: "ko-KR,en-US",
                    dpr: 2.625,
                    ww: 412,
                    wh: 780,
                    touch: !0,
                    pdf: !1,
                    fonts: 0
                }
            }))),
            S = {
                vid: l.vid,
                c: l.ct || "",
                p1: d[0],
                p2: d[1],
                p3: d[2],
                p4: d[3],
                t: d[4],
                sc: g,
                rid: u,
                fp: w,
                df: "",
                pow: m,
                pid: l.pid || "",
                st: l.st || ""
            },
            y = Object.entries(S)
                .map(([e, t]) => `${e}=${encodeURIComponent(t)}`)
                .join("&"),
            b = await this.client.get(
                `${PLAYER}/get-video-url-v2.php?${y}`,
                {
                    ...h,
                    "X-Requested-With": "XMLHttpRequest",
                    Accept: "application/json"
                }
            );

        let $;

        try {
            $ = JSON.parse(b.body);
        } catch (e) {
            throw new Error(`nhplayer 응답을 읽지 못했습니다 (HTTP ${b.statusCode}).`);
        }

        const x = String($?.url || "");

        if (
            200 !== b.statusCode ||
            !/^https?:\/\/[^\s"'<>]+$/.test(x)
        ) {
            throw new Error(`nhplayer: ${$?.error || `HTTP ${b.statusCode}`}`);
        }

        let E = "";

        try {
            E = String.fromCharCode(
                ...base64Decode(/[?&]s=([^&]*)/.exec(r)?.[1] || "")
            );
        } catch (e) {}

        return {
            url: x,
            subtitle: /^https?:\/\/[^\s"'<>]+$/.test(E) ? E : ""
        };
    }
}
